package cn.sixnine.filmlog;

final class PhotoMath {
    static final int[] METER_ISOS={25,32,40,50,64,80,100,125,160,200,250,320,400,500,640,800,1000,1250,1600,2000,2500,3200,4000,5000,6400};
    static int nearestMeterIso(double value){if(!Double.isFinite(value)||value<=0)return 400;int result=METER_ISOS[0];double best=Double.POSITIVE_INFINITY;for(int iso:METER_ISOS){double distance=Math.abs(Math.log(iso/value)/Math.log(2));if(distance<best){best=distance;result=iso;}}return result;}
    static int meterIsoStep(int current,int direction){int index=java.util.Arrays.binarySearch(METER_ISOS,current);if(index<0||Math.abs(direction)!=1)throw new IllegalArgumentException("请选择有效的测光ISO档位");return METER_ISOS[Math.max(0,Math.min(METER_ISOS.length-1,index+direction))];}
    static String meterMemo(String memo,int iso){if(java.util.Arrays.binarySearch(METER_ISOS,iso)<0)throw new IllegalArgumentException("请选择有效的测光ISO");java.util.ArrayList<String> parts=new java.util.ArrayList<>();for(String part:(memo==null?"":memo).split(" • ",-1))if(!part.isEmpty()&&!part.matches("ISO [0-9]+"))parts.add(part);parts.add("ISO "+iso);return String.join(" • ",parts);}
    static int effectiveIso(int iso,int stops){if(iso<0||iso>102400||stops< -2||stops>3)throw new IllegalArgumentException("ISO或增减感无效");return (int)Math.round(Math.scalb((double)iso,stops));}
    static String isoEiLabel(int iso,int stops){int effective=effectiveIso(iso,stops);return "ISO "+iso+(effective==iso?"":" · EI "+effective);}
    static final String[] FILMS={"不应用倒易律修正","ILFORD HP5+","ILFORD FP4+","ILFORD DELTA 100","ILFORD DELTA 400","ILFORD DELTA 3200","ILFORD Pan F+","ILFORD SFX","ILFORD XP2","ILFORD Ortho+","Kentmere 100","Kentmere 400"};
    static final double[] POWERS={1,1.31,1.26,1.26,1.41,1.33,1.33,1.43,1.31,1.25,1.26,1.30};
    static final double[] APERTURES={.7,1,1.4,2,2.8,4,5.6,8,11,16,22,32,45,64,90,128,180,256};
    static double apertureStep(double current,int direction){bounded(current,.7,256,"光圈");if(direction!=1&&direction!=-1)throw new IllegalArgumentException("光圈步进方向无效");if(direction>0){for(double value:APERTURES)if(value>current+1e-9)return value;return 256;}for(int i=APERTURES.length-1;i>=0;i--)if(APERTURES[i]<current-1e-9)return APERTURES[i];return .7;}
    static double bounded(double value,double low,double high,String label){if(!Double.isFinite(value)||value<low||value>high)throw new IllegalArgumentException(label+"须在 "+low+" 至 "+high+" 之间");return value;}
    static String apertureValue(String value){try{return decimal(bounded(Double.parseDouble(value.trim().replaceFirst("(?i)^f/?\\s*","")),.7,256,"光圈"));}catch(NumberFormatException error){throw new IllegalArgumentException("光圈请填数字，例如3.5");}}
    static double seconds(String value){try{String[] split=value.trim().replaceFirst("(?i)\\s*(s|秒)$", "").trim().split("/",-1);double seconds;if(split.length==1)seconds=Double.parseDouble(split[0]);else if(split.length==2){double numerator=Double.parseDouble(split[0]),denominator=Double.parseDouble(split[1]);if(numerator<=0||denominator<=0)throw new NumberFormatException();seconds=numerator/denominator;}else throw new NumberFormatException();return bounded(seconds,0.000001,86400,"快门秒数");}catch(NumberFormatException error){throw new IllegalArgumentException("快门请填秒数或分数，例如 0.5 或 1/125");}}
    static double compensation(String value){try{String raw=value.trim().replaceFirst("(?i)\\s*EV$", "").trim();if(raw.isEmpty())return 0;String[] parts=raw.split("/",-1);double result;if(parts.length==1)result=Double.parseDouble(parts[0].trim());else if(parts.length==2){double denominator=Double.parseDouble(parts[1].trim());if(denominator<=0)throw new NumberFormatException();result=Double.parseDouble(parts[0].trim())/denominator;}else throw new NumberFormatException();return bounded(result,-10,10,"曝光补偿");}catch(NumberFormatException e){throw new IllegalArgumentException("补偿请填写数字或分数，例如 +1/3 EV");}}
    static double nd(double seconds,double stops){bounded(seconds,0.000001,86400,"测得秒数");bounded(stops,0,30,"ND 档数");return checkedTime(seconds*Math.pow(2,stops));}
    static double reciprocity(double seconds,int film){if(film<0||film>=POWERS.length)throw new IllegalArgumentException("请选择胶片");bounded(seconds,0.000001,604800,"曝光秒数");return checkedTime(seconds<=1?seconds:Math.pow(seconds,POWERS[film]));}
    static double reciprocityPower(double seconds,double power){bounded(seconds,.000001,604800,"曝光秒数");bounded(power,1,3,"倒易律p");return checkedTime(seconds<=1?seconds:Math.pow(seconds,power));}
    static double checkedTime(double seconds){return bounded(seconds,0.000001,604800,"结果秒数（最长七天）");}
    static double shutter(double ev100,double iso,double aperture,double compensation){bounded(ev100,-20,30,"EV100");bounded(iso,1,102400,"ISO");bounded(aperture,0.7,256,"光圈");bounded(compensation,-10,10,"曝光补偿");return checkedTime(aperture*aperture/(Math.pow(2,ev100)*iso/100)*Math.pow(2,compensation));}
    static double aperture(double ev100,double iso,double seconds,double compensation){bounded(ev100,-20,30,"EV100");bounded(iso,1,102400,"ISO");bounded(seconds,.000001,604800,"快门秒数");bounded(compensation,-10,10,"曝光补偿");return bounded(Math.sqrt(seconds*Math.pow(2,ev100)*iso/100/Math.pow(2,compensation)),.7,256,"结果光圈");}
    static double ev100(double seconds,double iso,double aperture){bounded(seconds,0.000001,86400,"快门秒数");bounded(iso,1,102400,"ISO");bounded(aperture,0.7,256,"光圈");return Math.log(aperture*aperture/seconds*100/iso)/Math.log(2);}
    static final class Depth {double hyperfocal,near,far;}
    static Depth depth(double focal,double aperture,double distanceMeters,double circle){bounded(focal,1,2000,"焦距毫米");bounded(aperture,0.7,256,"光圈");bounded(distanceMeters,0.01,100000,"对焦距离米");bounded(circle,0.001,0.3,"弥散圈毫米");double distance=distanceMeters*1000;if(distance<=focal)throw new IllegalArgumentException("对焦距离必须大于焦距");double q=focal*focal/(aperture*circle),h=q+focal;Depth d=new Depth();d.hyperfocal=h/1000;d.near=q*distance/(q+distance-focal)/1000;d.far=distance>=h?Double.POSITIVE_INFINITY:q*distance/(q-distance+focal)/1000;return d;}
    static double flash(double gn100,double iso,double power,double distance){bounded(gn100,0.1,500,"ISO100 指数GN（米）");bounded(iso,1,102400,"ISO");bounded(power,1.0/1024,1,"输出比例");bounded(distance,0.1,1000,"闪光灯到主体距离米");return gn100*Math.sqrt(iso/100)*Math.sqrt(power)/distance;}
    static String shutterChoice(double seconds){return shutterText(seconds)+(seconds>=1?"s":"");}
    static String shutterText(double seconds){checkedTime(seconds);return seconds<1?"1/"+decimal(1/seconds):decimal(seconds);}
    static String decimal(double value){return java.math.BigDecimal.valueOf(value).setScale(4,java.math.RoundingMode.HALF_UP).stripTrailingZeros().toPlainString();}
}
